import{_ as t,o as a,c as i,a2 as d}from"./chunks/framework.DZhUhjDB.js";const p=JSON.parse('{"title":"� Módulo 06 — Forense Digital","description":"� Módulo 06 — Forense Digital","frontmatter":{"title":"� Módulo 06 — Forense Digital","description":"� Módulo 06 — Forense Digital"},"headers":[],"relativePath":"modules/red-team/06-forense-digital.md","filePath":"modules/red-team/06-forense-digital.md","lastUpdated":1787529976000}'),o={name:"modules/red-team/06-forense-digital.md"};function r(s,e,n,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="🔬-modulo-06-—-forense-digital" tabindex="-1">🔬 Módulo 06 — Forense Digital</h1><blockquote><p><strong>Nivel:</strong> Intermedio → Avanzado · <strong>Objetivo:</strong> reconstruir qué pasó en un sistema tras un incidente con evidencia íntegra y admisible usando el marco NIST SP 800-86.</p></blockquote><p><a href="./"><img src="https://img.shields.io/badge/Nivel-Intermedio%E2%86%92Avanzado-orange?style=flat-square" alt="Nivel"></a><a href="./"><img src="https://img.shields.io/badge/Enfoque-Blue%20Team-blue?style=flat-square" alt="Enfoque"></a><a href="./"><img src="https://img.shields.io/badge/Marco-NIST%20800--86-green?style=flat-square" alt="Marco"></a></p><hr><h2 id="📋-resumen" tabindex="-1">📋 Resumen</h2><table tabindex="0"><thead><tr><th>Atributo</th><th>Detalle</th></tr></thead><tbody><tr><td>🎯 <strong>Resultado</strong></td><td>Adquirir, analizar y reportar evidencia digital de forma forensemente válida</td></tr><tr><td>🧪 <strong>Práctica</strong></td><td>Volatility 3, The Sleuth Kit, Autopsy, plaso, KAPE, FTK Imager</td></tr><tr><td>🗂️ <strong>Portafolio</strong></td><td>Caso forense completo con metodología documentada</td></tr><tr><td>🔗 <strong>Requiere</strong></td><td><a href="./../05-post-explotacion/">Módulo 05 — Post-Explotación</a> (conocimiento de persistencia y movimiento lateral)</td></tr></tbody></table><hr><h2 id="🎯-objetivos-de-aprendizaje" tabindex="-1">🎯 Objetivos de aprendizaje</h2><p>Al completar este módulo deberías ser capaz de:</p><ul><li><strong>Cadena de custodia:</strong> establecer y mantener la integridad de la evidencia con hashing y documentación.</li><li><strong>Adquisición:</strong> crear imágenes bit a bit de discos y memoria RAM sin alterar evidencia.</li><li><strong>Análisis de disco:</strong> identificar archivos borrados, artefactos de Windows (Prefetch, Registry, $MFT) y reconstruir actividades.</li><li><strong>Análisis de memoria:</strong> extraer procesos, conexiones de red, inyecciones de código y credenciales de volcados de RAM.</li><li><strong>Timeline:</strong> construir una línea de tiempo unificada que reconstruya la secuencia de eventos.</li><li><strong>Reporte:</strong> documentar hallazgos de forma clara, profesional y legalmente sólida.</li><li><strong>Defensa:</strong> entender cómo se detecta y previene la evasión forense.</li></ul><hr><h2 id="🗂️-estructura-del-modulo" tabindex="-1">🗂️ Estructura del módulo</h2><table tabindex="0"><thead><tr><th>Carpeta</th><th>Contenido</th><th>Estado</th></tr></thead><tbody><tr><td><a href="./adquisicion-preservacion/"><code>adquisicion-preservacion/</code></a></td><td>Cadena de custodia, volatilidad y adquisición</td><td>✅ Completado</td></tr><tr><td><a href="./analisis-disco/"><code>analisis-disco/</code></a></td><td>Sistemas de archivos, particiones y herramientas de disco</td><td>✅ Completado</td></tr><tr><td><a href="./analisis-memoria/"><code>analisis-memoria/</code></a></td><td>Volatility 3 y análisis de RAM</td><td>✅ Completado</td></tr><tr><td><a href="./analisis-red/"><code>analisis-red/</code></a></td><td>Forense de tráfico de red</td><td>✅ Completado</td></tr><tr><td><a href="./analisis-metadatos/"><code>analisis-metadatos/</code></a></td><td>Metadatos ocultos en archivos</td><td>✅ Completado</td></tr><tr><td><a href="./timeline-reporte/"><code>timeline-reporte/</code></a></td><td>Línea de tiempo y reportes forenses</td><td>✅ Completado</td></tr><tr><td><a href="./herramientas/"><code>herramientas/</code></a></td><td>Comparativa y guía de herramientas forenses</td><td>✅ Completado</td></tr></tbody></table><h3 id="📚-contenido-detallado" tabindex="-1">📚 Contenido detallado</h3><h4 id="_1-adquisicion-y-preservacion" tabindex="-1">1. Adquisición y Preservación</h4><table tabindex="0"><thead><tr><th>Archivo</th><th>Contenido</th></tr></thead><tbody><tr><td><a href="./adquisicion-preservacion/01-cadena-custodia-adquisicion"><code>01-cadena-custodia-adquisicion.md</code></a></td><td>Cadena de custodia, hashing, orden de volatilidad, adquisición de disco y memoria, protocolos legales</td></tr></tbody></table><h4 id="_2-analisis-de-disco" tabindex="-1">2. Análisis de Disco</h4><table tabindex="0"><thead><tr><th>Archivo</th><th>Contenido</th></tr></thead><tbody><tr><td><a href="./analisis-disco/01-sistemas-archivos-img"><code>01-sistemas-archivos-img.md</code></a></td><td>Sistemas de archivos (NTFS, EXT4, APFS), particiones, $MFT, UsnJrnl, archivos borrados</td></tr><tr><td><a href="./analisis-disco/02-herramientas-disco"><code>02-herramientas-disco.md</code></a></td><td>The Sleuth Kit, Autopsy, FTK Imager, Recuva, PhotoRec, dd vs dc3dd</td></tr></tbody></table><h4 id="_3-analisis-de-memoria" tabindex="-1">3. Análisis de Memoria</h4><table tabindex="0"><thead><tr><th>Archivo</th><th>Contenido</th></tr></thead><tbody><tr><td><a href="./analisis-memoria/01-volatilidad-ram"><code>01-volatilidad-ram.md</code></a></td><td>Conceptos de volatilidad, adquisición de RAM, artefactos en memoria</td></tr><tr><td><a href="./analisis-memoria/02-herramientas-memoria"><code>02-herramientas-memoria.md</code></a></td><td>Volatility 3 completo, Volatility 2, Rekall, imageinfo, pslist, malfind, hashdump</td></tr></tbody></table><h4 id="_4-analisis-de-red" tabindex="-1">4. Análisis de Red</h4><table tabindex="0"><thead><tr><th>Archivo</th><th>Contenido</th></tr></thead><tbody><tr><td><a href="./analisis-red/01-forense-red"><code>01-forense-red.md</code></a></td><td>Captura de tráfico, análisis de paquetes, detección de C2, DNS forense, firewall logs</td></tr></tbody></table><h4 id="_5-analisis-de-metadatos" tabindex="-1">5. Análisis de Metadatos</h4><table tabindex="0"><thead><tr><th>Archivo</th><th>Contenido</th></tr></thead><tbody><tr><td><a href="./analisis-metadatos/01-metadatos-forenses"><code>01-metadatos-forenses.md</code></a></td><td>EXIF, metadatos de documentos, steganography, fingerprinting de archivos</td></tr></tbody></table><h4 id="_6-timeline-y-reporte" tabindex="-1">6. Timeline y Reporte</h4><table tabindex="0"><thead><tr><th>Archivo</th><th>Contenido</th></tr></thead><tbody><tr><td><a href="./timeline-reporte/01-construccion-timeline"><code>01-construccion-timeline.md</code></a></td><td>plaso/log2timeline, super timeline, filtrado por evento, correlación</td></tr><tr><td><a href="./timeline-reporte/02-reporte-forense"><code>02-reporte-forense.md</code></a></td><td>Estructura de reporte forense, plantilla profesional, ejemplos</td></tr></tbody></table><h4 id="_7-herramientas" tabindex="-1">7. Herramientas</h4><table tabindex="0"><thead><tr><th>Archivo</th><th>Contenido</th></tr></thead><tbody><tr><td><a href="./herramientas/01-herramientas-forenses"><code>01-herramientas-forenses.md</code></a></td><td>Comparativa completa, flujos de trabajo, KAPE, Velociraptor, CAINE</td></tr></tbody></table><hr><h2 id="🛠️-herramientas-principales" tabindex="-1">🛠️ Herramientas principales</h2><table tabindex="0"><thead><tr><th>Herramienta</th><th>Categoría</th><th>Uso principal</th></tr></thead><tbody><tr><td><strong>Volatility 3</strong></td><td>Memoria</td><td>Análisis de volcados de RAM</td></tr><tr><td><strong>The Sleuth Kit / Autopsy</strong></td><td>Disco</td><td>Análisis de imágenes de disco</td></tr><tr><td><strong>FTK Imager</strong></td><td>Adquisición</td><td>Creación de imágenes bit a bit</td></tr><tr><td><strong>plaso / log2timeline</strong></td><td>Timeline</td><td>Super timeline unificada</td></tr><tr><td><strong>KAPE</strong></td><td>Triage</td><td>Recolección rápida de artefactos</td></tr><tr><td><strong>dc3dd</strong></td><td>Adquisición</td><td>dd con hashing integrado</td></tr><tr><td><strong>Velociraptor</strong></td><td>Enterprise</td><td>Recolección remota de endpoints</td></tr><tr><td><strong>CAINE</strong></td><td>Live forensics</td><td>Distro Linux forense</td></tr><tr><td><strong>exiftool</strong></td><td>Metadatos</td><td>Extracción y edición de metadatos</td></tr><tr><td><strong>Wireshark</strong></td><td>Red</td><td>Análisis de tráfico de red</td></tr></tbody></table><hr><h2 id="⚖️-aviso-etico" tabindex="-1">⚖️ Aviso ético</h2><p>La forense digital <strong>solo</strong> se practica con:</p><ul><li>✅ Autorización legal explícita (orden judicial, contrato de investigación)</li><li>✅ Cadena de custodia documentada</li><li>✅ Trabajo sobre copias, nunca sobre evidencia original</li><li>✅ Herramientas forenses certificadas y validadas</li><li>❌ Nada de acceder a sistemas sin autorización legal</li><li>❌ Nada de alterar evidencia (incluso accidentalmente)</li><li>❌ Nada de usar evidencia para beneficio personal</li></ul><blockquote><p><strong>Importante:</strong> en muchos países, la recopilación y análisis de evidencia digital sin autorización constituye un delito grave. Siempre verifica la legalidad antes de iniciar un análisis forense.</p></blockquote><hr><h2 id="🔗-encaje-del-modulo-en-la-ruta" tabindex="-1">🔗 Encaje del módulo en la ruta</h2><p>Dentro de la <strong>Ruta 3 (Blue Team)</strong>, este módulo es la <strong>Fase C</strong>:</p><ol><li><code>01-reconocimiento-osint/</code> ← Reconocimiento</li><li><code>02-pentesting-red-team/</code> ← Pentesting</li><li><code>03-analisis-vulnerabilidades/</code> ← Análisis</li><li><code>04-explotacion-web/</code> ← Explotación</li><li><code>05-post-explotacion/</code> ← Post-explotación</li><li><strong><code>06-forense-digital/</code></strong> ← <strong>Este módulo</strong> (Fase C)</li><li><code>07-ingenieria-social/</code> ← Ingeniería social</li><li><code>08-criptografia/</code> ← Criptografía</li></ol><hr><h2 id="✅-checkpoint" tabindex="-1">✅ Checkpoint</h2><p>¿Puedes hacer lo siguiente sin guía?</p><ul><li>[ ] Crear una imagen bit a bit de un disco con dc3dd y verificar integridad con SHA-256</li><li>[ ] Documentar una cadena de custodia completa para una evidencia digital</li><li>[ ] Analizar una imagen de disco con Autopsy y recuperar archivos borrados</li><li>[ ] Analizar un volcado de memoria con Volatility 3 (pslist, netscan, malfind)</li><li>[ ] Construir una super timeline con plaso desde múltiples artefactos</li><li>[ ] Redactar un reporte forense profesional que responda preguntas del caso</li><li>[ ] Explicar cómo cada fase del proceso forense se relaciona con NIST SP 800-86</li></ul><p>Si todo es ✅, estás listo para el siguiente paso: <strong><a href="./../07-ingenieria-social/">Módulo 07 — Ingeniería Social</a></strong>.</p><hr><p><strong><a href="./../README">⬅ Volver a Ciberseguridad</a></strong> · <strong><a href="./../../RUTAS">🗺️ Ver Rutas</a></strong></p>',47)])])}const u=t(o,[["render",r]]);export{p as __pageData,u as default};
